# Generated by HCW 0.1.0 on 2026 11 09
"""
Add attachments to the HOPE Account fieldset.

`{type}_attachments` keeps the files of an account as a list of `{"file", "title"}` items, which
the push groups into the account sent to HOPE. People-only programs need the same accounts, so
the fieldset is also added to the People checker, with the prefixes of the Individual checker.
"""

from concurrency.utils import fqn
from django.db import transaction
from hope_flex_fields.models import DataChecker, DataCheckerFieldset, FieldDefinition, Fieldset
from hope_flex_fields.registry import field_registry
from hope_flex_fields.utils import get_common_attrs, get_kwargs_from_field_class
from packaging.version import Version

from country_workspace.contrib.hope.account_attachments import AccountAttachmentsField
from country_workspace.contrib.hope.constants import (
    ACCOUNT_ATTACHMENTS_FIELD,
    ACCOUNT_FIELDSET_NAME,
    INDIVIDUAL_CHECKER_NAME,
    PEOPLE_CHECKER_NAME,
)

_script_for_version = Version("0.1.0")

ATTRS = {"label": "Attachments", "required": False}


def _account_prefixes(checker_name: str, fieldset: Fieldset) -> set[str]:
    return set(
        DataCheckerFieldset.objects.filter(checker__name=checker_name, fieldset=fieldset).values_list(
            "prefix", flat=True
        )
    )


@transaction.atomic()
def forward() -> None:
    field_registry.register(AccountAttachmentsField)
    definition, __ = FieldDefinition.objects.get_or_create(
        name=AccountAttachmentsField.__name__,
        field_type=fqn(AccountAttachmentsField),
        defaults={"attrs": get_kwargs_from_field_class(AccountAttachmentsField, get_common_attrs())},
    )
    if not (fieldset := Fieldset.objects.filter(name=ACCOUNT_FIELDSET_NAME).first()):
        return
    fieldset.fields.update_or_create(
        name=ACCOUNT_ATTACHMENTS_FIELD, defaults={"definition": definition, "attrs": ATTRS}
    )
    if people_checker := DataChecker.objects.filter(name=PEOPLE_CHECKER_NAME).first():
        for prefix in _account_prefixes(INDIVIDUAL_CHECKER_NAME, fieldset):
            DataCheckerFieldset.objects.get_or_create(checker=people_checker, fieldset=fieldset, prefix=prefix)


@transaction.atomic()
def backward() -> None:
    if fieldset := Fieldset.objects.filter(name=ACCOUNT_FIELDSET_NAME).first():
        DataCheckerFieldset.objects.filter(checker__name=PEOPLE_CHECKER_NAME, fieldset=fieldset).delete()
        fieldset.fields.filter(name=ACCOUNT_ATTACHMENTS_FIELD).delete()
    for definition in FieldDefinition.objects.filter(field_type=fqn(AccountAttachmentsField)):
        if not definition.instances.exists():
            definition.delete()


class Scripts:
    requires = []
    operations = [(forward, backward)]
